@id("forbid-cag-001-sensitive-writes")
@source("policy.md#CAG-001")
forbid(
  principal,
  action == coding_agent::Action::"PreToolUse",
  resource
)
when {
  resource.name == "Write" &&
  context has normalized &&
  context.normalized.parse_ok &&
  context.normalized.path_present &&
  (
    context.normalized.path_contains_env ||
    context.normalized.path_has_credentials_component ||
    context.normalized.path_has_secrets_component
  )
};

